display.code:
.container {
  display: flex;
  justify-content: center;
}

.hidden {
  display: none;
}

margin.code:
/* Todas direcciones */
margin: 20px;
/* Vertical | Horizontal */
margin: 10px 20px;
/* Centrado */
margin: 0 auto;

position.code:
.parent {
  position: relative;
}

.child {
  position: absolute;
  top: 0;
  right: 0;
}

background.code:
.hero {
  background: linear-gradient(to right, #333, #000), url('hero.jpg');
  background-size: cover;
}

visibility.code:
.ghost {
  visibility: hidden;
  /* Ocupa espacio en blanco */
}

flex.code:
.item {
  flex: 1; /* Ocupa todo el espacio posible */
}
.fixed {
  flex: 0 0 200px; /* Ancho fijo de 200px */
}

align-items.code:
.container {
  display: flex;
  align-items: center; /* Centrado vertical */
  height: 100vh;
}

grid-template-rows.code:
.page {
  display: grid;
  grid-template-rows: 60px 1fr 40px; /* Header Main Footer */
  height: 100vh;
}
